async () => {
window.__ev=[]; for (const n of ['conversation_closed:agent_0x99_handler','conversation_closed:recruiter','conversation_closed:patricia_phone','global_variable_changed:mission_complete','global_variable_changed:flag4_submitted','phone_call_answered:recruiter','phone_call_declined:recruiter','phone_call_missed:recruiter','phone_call_answered:agent_0x99_handler','phone_call_declined:agent_0x99_handler','phone_call_missed:agent_0x99_handler','phone_call_answered:patricia_phone','objective_task_completed:call_in_after_sweep','game_loaded']) window.eventDispatcher.on(n, (d)=>window.__ev.push(n+'@'+Math.round(performance.now()/100)/10+(d&&d.callback?' callback':'')+(d&&d.reload?' reload':'')+(d&&typeof d.answerSeconds==='number'?' as='+d.answerSeconds:''))); return true;

}

async () => {
const o=window.endingCheck.openOptional(); for(const t of o){ try{ window.objectivesManager.completeTask(t.taskId);}catch(e){} } return window.endingCheck.openOptional().map(t=>t.taskId);

}

